url_options.data:
{
  "size": 0,
  "query": {
    "bool": {
      "filter": [
        {
          "range": {
            "@timestamp": {
              "gte": "${__from}",
              "lte": "${__to}"
            }
          }
        },
        {
          "wildcard": {
            "session.media.bu": "${bu}"
          }
        },
        {
          "wildcard": {
            "session.media.type": "${type}"
          }
        },
        {
          "wildcard": {
            "session.media.id": "${media_id}"
          }
        },
        {
          "query_string": {
            "query": "session.media.swisstxt:${swisstxt:raw}"
          }
        },
        {
          "terms": {
            "event_name": [
              "ERROR",
              "START"
            ]
          }
        }
      ]
    }
  },
  "aggs": {
    "g": {
      "terms": {
        "field": "session.player.platform",
        "size": 50,
        "order": {
          "starts": "desc"
        }
      },
      "aggs": {
        "errors": {
          "filter": {
            "bool": {
              "filter": [
                {
                  "term": {
                    "event_name": "ERROR"
                  }
                },
                {
                  "term": {
                    "data.business_error": false
                  }
                }
              ],
              "must_not": [
                {
                  "terms": {
                    "data.error_type": [
                      "DRM_NOT_SUPPORTED",
                      "CONNECTION_ERROR"
                    ]
                  }
                }
              ]
            }
          }
        },
        "starts": {
          "filter": {
            "term": {
              "event_name": "START"
            }
          }
        },
        "http_5xx": {
          "filter": {
            "bool": {
              "filter": [
                {
                  "term": {
                    "event_name": "ERROR"
                  }
                },
                {
                  "term": {
                    "data.business_error": false
                  }
                },
                {
                  "query_string": {
                    "query": "data.message:(\"Response code: 500\" OR \"Response code: 501\" OR \"Response code: 502\" OR \"Response code: 503\" OR \"Response code: 504\")"
                  }
                }
              ],
              "must_not": [
                {
                  "terms": {
                    "data.error_type": [
                      "DRM_NOT_SUPPORTED",
                      "CONNECTION_ERROR"
                    ]
                  }
                }
              ]
            }
          }
        },
        "http_504": {
          "filter": {
            "bool": {
              "filter": [
                {
                  "term": {
                    "event_name": "ERROR"
                  }
                },
                {
                  "term": {
                    "data.business_error": false
                  }
                },
                {
                  "query_string": {
                    "query": "data.message:\"Response code: 504\""
                  }
                }
              ],
              "must_not": [
                {
                  "terms": {
                    "data.error_type": [
                      "DRM_NOT_SUPPORTED",
                      "CONNECTION_ERROR"
                    ]
                  }
                }
              ]
            }
          }
        },
        "error_rate": {
          "bucket_script": {
            "buckets_path": {
              "err": "errors>_count",
              "sess": "starts>_count"
            },
            "script": "params.sess > 0 ? params.err / params.sess : 0"
          }
        },
        "rate_504": {
          "bucket_script": {
            "buckets_path": {
              "e": "http_504>_count",
              "sess": "starts>_count"
            },
            "script": "params.sess > 0 ? params.e / params.sess : 0"
          }
        },
        "success_rate": {
          "bucket_script": {
            "buckets_path": {
              "err": "errors>_count",
              "sess": "starts>_count"
            },
            "script": "params.sess > 0 ? 1 - params.err / params.sess : 0"
          }
        },
        "success_excl_5xx": {
          "bucket_script": {
            "buckets_path": {
              "err": "errors>_count",
              "h5": "http_5xx>_count",
              "sess": "starts>_count"
            },
            "script": "params.sess > 0 ? 1 - (params.err - params.h5) / params.sess : 0"
          }
        },
        "p50_load_time": {
          "filter": {
            "term": {
              "event_name": "START"
            }
          },
          "aggs": {
            "percentile": {
              "percentiles": {
                "field": "session.qoe_timings.total",
                "percents": [
                  50
                ]
              }
            }
          }
        }
      }
    }
  }
}

